                case "unstop_until": unstop_until = V.ToDouble(v); return;
                case "skin_until": skin_until = V.ToDouble(v); return;
                default:
                    if (extra == null) extra = new Dictionary<string, object>();
                    extra[key] = v;
                    return;
            }
        }

